browser.runtime.onMessage.addListener((e,r,t)=>{if(e.type==="GET_DIMENSIONS")return t({scrollWidth:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth),scrollHeight:Math.max(document.documentElement.scrollHeight,document.body.scrollHeight),viewportWidth:window.innerWidth,viewportHeight:window.innerHeight}),!0;if(e.type==="SCROLL_TO")return window.scrollTo(e.x,e.y),requestAnimationFrame(()=>{requestAnimationFrame(()=>{t({success:!0,x:window.scrollX,y:window.scrollY})})}),!0;if(e.type==="GET_META")return t({title:document.title||"Untitled",url:location.href,favicon:document.querySelector('link[rel~="icon"]')?.href||""}),!0});
